insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('104', 'agua-micelar', 'Agua Micelar', (select id from public.brands where name = 'Sulderm'), 'El agua micelar es ideal para una limpieza práctica y efectiva, perfecta para comenzar o finalizar el día.', 'El agua micelar es ideal para una limpieza práctica y efectiva, perfecta para comenzar o finalizar el día. Gracias a su tecnología micelar, atrae y elimina impurezas y maquillaje sin necesidad de frotar. Su fórmula 3 en 1 limpia, desmaquilla e hidrata, dejando la piel fresca, suave y equilibrada, sin sensación grasosa.
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('105', 'espuma-limpieza', 'Espuma de limpieza', (select id from public.brands where name = 'Sulderm'), 'La espuma de limpieza proporciona una higiene más profunda, ideal para complementar la rutina y eliminar residuos que se acumulan en la piel.', 'La espuma de limpieza proporciona una higiene más profunda, ideal para complementar la rutina y eliminar residuos que se acumulan en la piel. Su textura ligera y envolvente permite limpiar en profundidad sin resecar. Su fórmula 3 en 1 limpia, desmaquilla e hidrata, dejando la piel purificada, luminosa y visiblemente más uniforme.
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('106', 'scrumb-fisicoquimico', 'Scrub facial y corporal 5% ac glicólico', null, null, 'La exfoliación combina acción física y química para eliminar células muertas, desobstruir poros y eliminar impurezas acumuladas, renovando la superficie de la piel. Este paso es indispensable para mejorar la textura, estimular la regeneración celular y devolver luminosidad. Además, favorece la absorción de los activos aplicados posteriormente. Uso semanal.
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('107', 'crema-corporal', 'Crema hidratante corporal supreme Urea', null, 'Una fórmula súper hidratante, de rápida absorción que no deja efecto graso, para una piel suave, hidratada y radiante durante todo el día.', 'Una fórmula súper hidratante, de rápida absorción que no deja efecto graso, para una piel suave, hidratada y radiante durante todo el día. Un blend de activos hidratantes y nutritivos, rico en omegas, micronutrientes esenciales y aminoácidos. Urea + karité Hydra Nutriskin® Rosa de Jericó', 48000, null, false, 0, 'active', false, now() - interval '3 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('108', 'crema-corporal-celulitis', 'Anticelulitis', null, null, 'Crema corporal reductora de la celulitis con una doble eficacia: Ayuda a mejorar visiblemente la apariencia de la piel de naranja mientras ayuda a disminuir la retención de líquidos mejorando la microcirculación.', 48000, null, false, 0, 'active', false, now() - interval '4 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('109', 'hydra-filler-light', 'Hydra Filler Light', null, 'La hidratación facial es fundamental para mantener el equilibrio y la salud de la piel.', 'La hidratación facial es fundamental para mantener el equilibrio y la salud de la piel. Hydra Filler Light está formulado con una textura liviana, ideal para pieles mixtas a grasas o para quienes buscan una hidratación sin sensación pesada. Su combinación de activos ayuda a restaurar la barrera cutánea, aportando frescura, suavidad y luminosidad, mientras mantiene la piel protegida durante el día.', 29600, null, false, 0, 'active', false, now() - interval '5 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('110', 'hydra-filler-intense', 'Hydra Filler Intense', null, 'La hidratación profunda es clave para devolverle a la piel su vitalidad y elasticidad.', 'La hidratación profunda es clave para devolverle a la piel su vitalidad y elasticidad. Hydra Filler Intense presenta una textura más rica y nutritiva, ideal para pieles secas o deshidratadas que requieren un mayor aporte de hidratación. Su fórmula concentrada ayuda a reparar la barrera protectora, mejorar la tersura y aportar luminosidad, dejando la piel visiblemente más saludable y confortable. Ideal para uso diario.', 29600, null, false, 0, 'active', false, now() - interval '6 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('111', 'hydra-age-oro-edad', 'Hydra edad de oro', null, 'Este tratamiento hidratante está diseñado para cubrir las necesidades de las pieles más maduras, brindando una hidratación profunda y sostenida.', 'Este tratamiento hidratante está diseñado para cubrir las necesidades de las pieles más maduras, brindando una hidratación profunda y sostenida. Su fórmula con activos de alto poder nutritivo ayuda a reforzar la barrera protectora de la piel, mejorar la tersura y devolver luminosidad. Ideal para acompañar los procesos naturales de la piel con el paso del tiempo, aportando firmeza, confort y un aspecto más saludable.rnrn', 32700, null, false, 0, 'active', false, now() - interval '7 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('112', 'protector-solar-con-color', 'Protector Solar con Color', null, 'Además de brindar alta protección solar, esta emulsión facial con color ayuda a unificar el tono de la piel, disimulando imperfecciones de forma natural.', 'Además de brindar alta protección solar, esta emulsión facial con color ayuda a unificar el tono de la piel, disimulando imperfecciones de forma natural. Su textura de toque seco permite un acabado mate y liviano, ideal para el uso diario. Protege frente a los rayos UVA/UVB y la luz azul, aportando un efecto saludable y uniforme en la piel.', 35500, null, true, 0, 'active', false, now() - interval '8 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('113', 'protector-solar-sin-color', 'Protector Solar sin Color', null, 'Esta emulsión facial está diseñada para proteger la piel del rostro de la exposición diaria al sol.', 'Esta emulsión facial está diseñada para proteger la piel del rostro de la exposición diaria al sol. Su fórmula liviana actúa contra los rayos UVA/UVB y la luz azul, previniendo el envejecimiento prematuro y la aparición de manchas. Aporta hidratación sin dejar residuos grasos, logrando un acabado confortable y de rápida absorción.', 35500, null, true, 0, 'active', false, now() - interval '9 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('114', 'protector-exel-sin-color', 'EXEL pantalla fotoprotectora SPF 60', (select id from public.brands where name = 'EXEL'), 'La Pantalla Fotoprotectora Clarificante SPF60 de Exel es la solución ideal para quienes buscan una protección efectiva contra los dañinos rayos UV.', 'La Pantalla Fotoprotectora Clarificante SPF60 de Exel es la solución ideal para quienes buscan una protección efectiva contra los dañinos rayos UV. Formulada especialmente para pieles con tendencia a las manchas, esta crema de tono claro se adapta perfectamente al rostro, cuello y escote, brindando una cobertura uniforme y segura. Su factor de protección solar 60 garantiza una defensa robusta, permitiendo disfrutar del sol sin preocupaciones. Incorporar la Pantalla Fotoprotectora Clarificante SPF60 en tu rutina de cuidado de la piel es un paso esencial para mantener un cutis saludable y radiante. Protege tu piel de los efectos nocivos del sol y previene la aparición de manchas, asegurando que tu belleza natural brille en cualquier ocasión. Con Exel, cuida tu piel con confianza y efectividad.', 46000, null, true, 1, 'active', false, now() - interval '10 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('115', 'protector-via-oral', 'Protector via Oral', null, null, '', 42000, null, false, 0, 'active', true, now() - interval '11 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('116', 'despigment-clear-complex', 'Clear complexión despigmentante', null, 'Clear Complexion, innovador y poderoso complejo despigmentante que permite unificar el color de la piel logrando el aspecto deseado.', 'Clear Complexion, innovador y poderoso complejo despigmentante que permite unificar el color de la piel logrando el aspecto deseado. Su formulación sinérgica aporta luminosidad, brillo y tersura a la piel del rostro, cuello, escote y manos.', 48000, null, false, 0, 'active', false, now() - interval '12 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('117', 'ultra-defense-acido-glicolico-10', 'Ac glicolico 10% (ULTRA DEFENSE)', null, null, 'Pensada para combatir el envejecimiento cutáneo, favoreciendo la renovación celular, fortaleciendo la barrera cutánea y devolviendo su elasticidad y flexibilidad. Ideal uso nocturno.', 38000, null, true, 10, 'active', false, now() - interval '13 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('118', 'home-care-contorno-bolsas-y-ojeras', 'Contorno de ojos bolsas y ojeras', (select id from public.brands where name = 'Sulderm'), null, 'Formulado para tratar bolsas y ojeras, este contorno de ojos ayuda a descongestionar la zona periocular, favoreciendo la microcirculación y reduciendo la apariencia de hinchazón y oscurecimiento. Su acción contribuye a iluminar la mirada, mejorar el tono de la piel y devolver un aspecto más fresco y descansado. Ideal para quienes buscan revitalizar el contorno de ojos y mejorar visiblemente su apariencia.', 32000, null, false, 0, 'active', false, now() - interval '14 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('119', 'home-care-ojeras-vasculares', 'Home Care Ojeras Vasculares', null, null, '', 29600, null, false, 0, 'active', false, now() - interval '15 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
