insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('121', 'lips-glow-hidratante', 'Lips glow hidratación + volumen', null, 'El cuidado de los labios es esencial para lucir una boca hidratada y luminosa, mejorar la textura y disminuir sus arrugas.', 'El cuidado de los labios es esencial para lucir una boca hidratada y luminosa, mejorar la textura y disminuir sus arrugas. La exfoliación e hidratación son dos pasos fundamentales de una rutina. Aseguran una regeneración efectiva, mejorando la calidad, el aspecto, la tersura y su luminosidad.', 32800, null, false, 0, 'active', false, now() - interval '17 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('123', 'serum-edad-oro', 'Serum Edad de Oro', null, 'Este serum nutritivo está especialmente formulado para pieles maduras y secas que requieren un cuidado intensivo.', 'Este serum nutritivo está especialmente formulado para pieles maduras y secas que requieren un cuidado intensivo. Su textura oleosa aporta nutrición profunda, ayudando a restaurar la barrera cutánea y mejorar la elasticidad de la piel. Actúa sobre los signos del envejecimiento, devolviendo suavidad, luminosidad y confort, dejando la piel visiblemente más revitalizada y flexible.', 33000, null, false, 0, 'active', false, now() - interval '18 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('124', 'sermun-expression', 'Serum Expression', null, null, 'El serum Xpression está formulado para actuar específicamente sobre las líneas de expresión, ayudando a suavizar visiblemente arrugas dinámicas y prevenir su formación. Gracias a su acción focalizada, relaja la apariencia de la piel sin perder naturalidad, aportando un aspecto más descansado y rejuvenecido.
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('125', 'vitamina-c-sulderm', 'Vitamina C', (select id from public.brands where name = 'Sulderm'), 'Monodosis antioxidantes de uso diario.', 'Monodosis antioxidantes de uso diario. Fórmula a base de Vitamina C + E + Hydra Skin + Ácido Ferúlico, una combinación de potentes antioxidantes que ayudan a proteger la piel contra los radicales libres y agentes externos, ayudando a prevenir y a mejorar los signos del envejecimiento, las arrugas finas y promoviendo la producción de colágeno y elastina para una piel más iluminada y rejuvenecida.', 75000, null, true, 6, 'active', false, now() - interval '20 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
