insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('128', 'rosatopis-serum', 'ROSATOPIC Serum', (select id from public.brands where name = 'Sulderm'), 'Este serum está especialmente formulado para pieles sensibles con tendencia a la rosácea, brindando una acción calmante y fortalecedora.', 'Este serum está especialmente formulado para pieles sensibles con tendencia a la rosácea, brindando una acción calmante y fortalecedora. Su textura fresca y aterciopelada ayuda a reforzar los capilares y la epidermis, mejorando la vasoconstricción y reduciendo visiblemente las rojeces. Contribuye a equilibrar la piel, aportando hidratación y confort, y mejorando progresivamente su aspecto general.', 32000, null, false, 0, 'active', false, now() - interval '23 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
