insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('131', 'serum-acneplur', 'ACNEPLUR Serum', (select id from public.brands where name = 'Sulderm'), 'Este serum actúa de forma específica sobre las imperfecciones, ayudando a disminuir los síntomas del acné y regular la producción de sebo.', 'Este serum actúa de forma específica sobre las imperfecciones, ayudando a disminuir los síntomas del acné y regular la producción de sebo. Su fórmula liviana favorece el equilibrio de la microbiota cutánea, mejorando el aspecto general de la piel y reduciendo la apariencia de poros e irregularidades. Ideal para lograr una piel más equilibrada, uniforme y saludable.', 33000, null, false, 0, 'active', false, now() - interval '26 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('132', 'espuma-acneplur-foam', 'ACNEPLUR Foam', (select id from public.brands where name = 'Sulderm'), 'Esta espuma de limpieza está especialmente formulada para pieles oleosas y con tendencia acnéica.', 'Esta espuma de limpieza está especialmente formulada para pieles oleosas y con tendencia acnéica. Ayuda a eliminar impurezas, exceso de sebo y residuos acumulados, sin alterar la barrera natural de la piel. Su acción contribuye a purificar, equilibrar y preparar la piel para potenciar los tratamientos posteriores, dejándola fresca, limpia y con una textura más uniforme.', 32000, null, false, 0, 'active', false, now() - interval '27 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
insert into public.products (sku, slug, name, brand_id, tagline, description, price, compare_at_price, track_stock, stock, status, requires_prescription, created_at) values ('133', 'crema-sulderm-hydra-acneplur', 'ACNEPLUR Hydra', (select id from public.brands where name = 'Sulderm'), 'Este hidratante está diseñado para aportar el equilibrio justo que las pieles oleosas y acnéicas necesitan.', 'Este hidratante está diseñado para aportar el equilibrio justo que las pieles oleosas y acnéicas necesitan. Su fórmula ayuda a hidratar sin generar oleosidad, restaurando la barrera cutánea y contribuyendo a mantener la piel protegida. Actúa en sinergia con el resto de la línea, mejorando la textura y favoreciendo un aspecto más saludable y controlado.', 29800, null, false, 0, 'active', false, now() - interval '28 seconds') on conflict (sku) do update set slug = excluded.slug, name = excluded.name, brand_id = excluded.brand_id, tagline = excluded.tagline, description = excluded.description, price = excluded.price, compare_at_price = excluded.compare_at_price, track_stock = excluded.track_stock, stock = greatest(excluded.stock, public.products.reserved_stock), status = 'active', requires_prescription = excluded.requires_prescription, created_at = excluded.created_at;
